<?php
namespace App\Domain\Credits;
use App\Models\CreditLedger; use App\Models\CreditWallet; use Illuminate\Support\Facades\DB; use RuntimeException;
final class CreditService
{
 public function reserve(string $walletId,float $amount,string $key,?string $userId=null): CreditWallet { if($amount<=0)throw new RuntimeException('Rezervasyon miktarı pozitif olmalıdır.'); return DB::transaction(function()use($walletId,$amount,$key,$userId){$wallet=CreditWallet::query()->lockForUpdate()->findOrFail($walletId); if(CreditLedger::where('idempotency_key',$key)->exists())return $wallet; $available=$wallet->subscription_balance+$wallet->promotion_balance+$wallet->purchased_balance-$wallet->reserved_balance;if($available<$amount)throw new RuntimeException('Yetersiz kredi.');$before=$available;$wallet->increment('reserved_balance',$amount);CreditLedger::create(['organization_id'=>$wallet->organization_id,'user_id'=>$userId,'wallet_id'=>$wallet->id,'product_id'=>$wallet->product_id,'credit_type'=>$wallet->credit_type,'transaction_type'=>'reservation','amount'=>-$amount,'previous_balance'=>$before,'next_balance'=>$before-$amount,'idempotency_key'=>$key,'description'=>'Analiz kredisi rezervasyonu','occurred_at'=>now()]);return $wallet->refresh();},3); }
 public function settle(string $walletId,float $reserved,float $actual,string $key,?string $userId=null): CreditWallet { if($actual<0||$actual>$reserved)throw new RuntimeException('Geçersiz settlement miktarı.'); return DB::transaction(function()use($walletId,$reserved,$actual,$key,$userId){$w=CreditWallet::lockForUpdate()->findOrFail($walletId);if(CreditLedger::where('idempotency_key',$key)->exists())return $w;$before=$w->subscription_balance+$w->promotion_balance+$w->purchased_balance-$w->reserved_balance;$remaining=$actual;foreach(['subscription_balance','promotion_balance','purchased_balance'] as $bucket){$used=min((float)$w->{$bucket},$remaining);$w->{$bucket}-=$used;$remaining-=$used;}if($remaining>0)throw new RuntimeException('Kredi bakiyesi negatif olamaz.');$w->reserved_balance=max(0,$w->reserved_balance-$reserved);$w->save();CreditLedger::create(['organization_id'=>$w->organization_id,'user_id'=>$userId,'wallet_id'=>$w->id,'product_id'=>$w->product_id,'credit_type'=>$w->credit_type,'transaction_type'=>'settlement','amount'=>-$actual,'previous_balance'=>$before,'next_balance'=>$before+($reserved-$actual),'idempotency_key'=>$key,'description'=>'Gerçek kullanım settlement','occurred_at'=>now()]);return $w;},3); }
}
